import{describe,it,expect,beforeEach}from"vitest";import{CapitalMatchGame}from"../../frontend/capital-match-up/script.js";const mockLocations=[{id:"ap",name:"Andhra Pradesh",capital:"Amaravati"},{id:"mh",name:"Maharashtra",capital:"Mumbai"},{id:"ka",name:"Karnataka",capital:"Bengaluru"},{id:"dl",name:"Delhi",capital:"New Delhi"},{id:"tn",name:"Tamil Nadu",capital:"Chennai"},{id:"wb",name:"West Bengal",capital:"Kolkata"}];describe("Capital Match-Up Game Logic",()=>{let e;beforeEach(()=>{e=new CapitalMatchGame(mockLocations)}),it("should initialize stats correctly",()=>{expect(e.score).toBe(0),expect(e.roundsCompleted).toBe(0),expect(e.matchedPairsCount).toBe(0)}),it("should generate requested number of round items from dataset without duplicates",()=>{const t=e.generateRoundItems(5);expect(t.length).toBe(5);const a=t.map(e=>e.id),c=new Set(a);expect(c.size).toBe(5)}),it("should validate a correct match and award score points",()=>{e.generateRoundItems(5);const t=e.currentRoundItems[0],a=e.checkMatch(t.id,t.capital);expect(a.isMatch).toBe(!0),expect(a.matchedPairsCount).toBe(1),expect(e.score).toBe(20)}),it("should penalize score on incorrect match",()=>{e.generateRoundItems(5);const t=e.currentRoundItems[0],a=e.checkMatch(t.id,"WrongCapitalCity");expect(a.isMatch).toBe(!1),expect(a.matchedPairsCount).toBe(0),expect(e.score).toBe(0)}),it("should complete round when all 5 pairs are matched",()=>{e.generateRoundItems(5),e.currentRoundItems.forEach(t=>{e.checkMatch(t.id,t.capital)}),expect(e.matchedPairsCount).toBe(5),expect(e.roundsCompleted).toBe(1),expect(e.score).toBe(100)}),it("should reset game state completely",()=>{e.generateRoundItems(5),e.checkMatch(e.currentRoundItems[0].id,e.currentRoundItems[0].capital),expect(e.score).toBe(20),e.resetGame(),expect(e.score).toBe(0),expect(e.roundsCompleted).toBe(0),expect(e.matchedPairsCount).toBe(0)})});